)

type fakeDynamo struct {
	items     []map[string]interface{}
	indexes   []string
(tableOK)  bool
}

type attr struct {
	S *string
	N *string
}

func (f *fakeDynamo) serve(w http.ResponseWriter, r *http.Request) {
	body, _ := ioutil.ReadAll(r.Body)
	var in map[string]interface{}
	if err := json.Unmarshal(body, &in); err != nil {
		http.Error(w, err.Error(), http.StatusBadRequest)
		return
	}
	target := r.Header.Get("X-Amz-Target")
	out := map[string]interface{}{}
	switch target {
	case "DynamoDB.PutItem":
		item := in["Item"].(map[string]interface{})
		f.items = append(f.items, item)
	case "DynamoDB.UpdateItem":
		key := in["Key"].(map[string]interface{})
		exprs := in["ExpressionAttributeValues"].(map[string]interface{})
		for i := range f.items {
			if sameKey(f.items[i], key) {
				f.items[i]["CreatedAtDate"] = map[string]interface{}{"S": exprs[":date"].(map[string]interface{})["S"]}
			}
		}
	case "DynamoDB.Scan":
		items := make([]interface{}, 0, len(f.items))
		for _, it := range f.items {
			items = append(items, it)
		}
		out["Items"] = items
		out["Count"] = len(items)
	case "DynamoDB.Query":
		exprs := in["ExpressionAttributeValues"].(map[string]interface{})
		date := exprs[":date"].(map[string]interface{})["S"].(string)
		start := toInt(exprs[":start"].(map[string]interface{})["N"].(string))
		end := toInt(exprs[":end"].(map[string]interface{})["N"].(string))
		if _, ok := exprs[":eventNamespace"]; ok {
			panic("EventNamespace must not be used by the date based search")
		}
		if len(exprs) != 3 {
			panic(fmt.Sprintf("expected 3 bound values, got %v", len(exprs)))
		}
		items := make([]interface{}, 0, len(f.items))
		for _, it := range f.items {
			d, ok := it["CreatedAtDate"].(map[string]interface{})["S"]
			if !ok || d.(string) != date {
				continue
			}
			created := toInt(it["CreatedAt"].(map[string]interface{})["N"].(string))
			if created >= start && created <= end {
				items = append(items, it)
			}
		}
		out["Items"] = items
		out["Count"] = len(items)
	case "DynamoDB.DescribeTable":
		indexes := make([]interface{}, 0, len(f.indexes))
		for _, idx := range f.indexes {
			indexes = append(indexes, map[string]interface{}{"IndexName": idx, "IndexStatus": "ACTIVE"})
		}
		out["Table"] = map[string]interface{}{
			"TableName":             in["TableName"],
			"TableStatus":           "ACTIVE",
			"GlobalSecondaryIndexes": indexes,
		}
	default:
		panic("unexpected target " + target)
	}
	data, _ := json.Marshal(out)
	w.Header().Set("Content-Type", "application/x-amz-json-1.0")
	w.Write(data)
}

func toInt(s string) int64 {
	var v int64
	fmt.Sscanf(s, "%d", &v)
	return v
}

func sameKey(item, key map[string]interface{}) bool {
	return eq(item["SessionID"], key["SessionID"]) && eq(item["EventIndex"], key["EventIndex"])
}

func eq(a, b interface{}) bool {
	am, ok := a.(map[string]interface{})
	if !ok {
		return false
	}
	bm, ok := b.(map[string]interface{})
	if !ok {
		return false
	}
	return fmt.Sprintf("%v", am) == fmt.Sprintf("%v", bm)
}

func newFakeLog(t *testing.T, indexes []string) (*Log, *fakeDynamo) {
	f := &fakeDynamo{indexes: indexes}
	srv := httptest.NewServer(http.HandlerFunc(f.serve))
	t.Cleanup(srv.Close)
	session, err := awssession.NewSession(&aws.Config{
		Region:      aws.String("us-east-1"),
		Credentials: credentials.NewStaticCredentials("id", "secret", "token"),
		Endpoint:    aws.String(srv.URL),
	})
	if err != nil {
		t.Fatal(err)
	}
