package dynamoevents

import (
	"context"
	"encoding/json"
	"io"
	"net/http"
	"net/http/httptest"
	"sync"
	"testing"
	"time"

	"github.com/gravitational/teleport/lib/utils"

	"github.com/aws/aws-sdk-go/aws"
	"github.com/aws/aws-sdk-go/aws/credentials"
	awssession "github.com/aws/aws-sdk-go/aws/session"
	"github.com/aws/aws-sdk-go/service/dynamodb"
 log "github.com/sirupsen/logrus"
)

type recorder struct {
	mu   sync.Mutex
	reqs []recordedReq
}

type recordedReq struct {
	action string
	body   map[string]interface{}
}

func (r *recorder) record(action string, body map[string]interface{}) {
	r.mu.Lock()
	defer r.mu.Unlock()
	r.reqs = append(r.reqs, recordedReq{action: action, body: body})
}

func (r *recorder) actions() []string {
	r.mu.Lock()
	defer r.mu.Unlock()
	var out []string
	for _, q := range r.reqs {
		out = append(out, q.action)
	}
	return out
}

// newMockServer returns a server answering the operations the tested code
// paths use: Scan, UpdateItem, Query, DescribeTable, PutItem.
func newMockServer(t *testing.T, r *recorder, items []map[string]interface{}, indexes []string) *httptest.Server {
	encode := func(v interface{}) string {
		data, err := json.Marshal(v)
		if err != nil {
			t.Fatal(err)
		}
		return string(data)
	}
	return httptest.NewServer(http.HandlerFunc(func(w http.ResponseWriter, req *http.Request) {
		data, _ := io.ReadAll(req.Body)
		var body map[string]interface{}
		_ = json.Unmarshal(data, &body)
		action := req.Header.Get("X-Amz-Target")
		r.record(action, body)
		w.Header().Set("Content-Type", "application/x-amz-json-1.0")
		switch {
		case len(action) > 4 && action[len(action)-4:] == "Scan":
			if items == nil {
				items = []map[string]interface{}{}
			}
			io.WriteString(w, encode(map[string]interface{}{"Items": items, "Count": len(items), "ScannedCount": len(items)}))
		case len(action) > 10 && action[len(action)-10:] == "UpdateItem":
			io.WriteString(w, encode(map[string]interface{}{}))
		case len(action) > 5 && action[len(action)-5:] == "Query":
			io.WriteString(w, encode(map[string]interface{}{"Items": []map[string]interface{}{}, "Count": 0}))
		case len(action) > 12 && action[len(action)-12:] == "DescribeTable":
			var gsis []map[string]interface{}
			for _, name := range indexes {
				gsis = append(gsis, map[string]interface{}{"IndexName": name, "IndexStatus": "ACTIVE"})
			}
			io.WriteString(w, encode(map[string]interface{}{"Table": map[string]interface{}{
				"TableName":              "events",
				"TableStatus":            "ACTIVE",
				"GlobalSecondaryIndexes": gsis,
			}}))
		case len(action) > 7 && action[len(action)-7:] == "PutItem":
			io.WriteString(w, encode(map[string]interface{}{}))
		default:
			t.Logf("unexpected action %v body %v", action, string(data))
			io.WriteString(w, encode(map[string]interface{}{}))
		}
	}))
}

func newTestLog(t *testing.T, url string) *Log {
	sess, err := awssession.NewSession(&aws.Config{
		Region:      aws.String("us-west-2"),
		Credentials: credentials.NewStaticCredentials("id", "secret", "token"),
	})
	if err != nil {
		t.Fatal(err)
	}
	return &Log{
		Entry: log.NewEntry(log.StandardLogger()),
		Config: Config{
			Tablename:      "events",
			UIDGenerator:   utils.NewRealUID(),
			ReadCapacityUnits:  DefaultReadCapacityUnits,
			WriteCapacityUnits: DefaultWriteCapacityUnits,
		},
		svc: dynamodb.New(sess, aws.NewConfig().WithEndpoint(url)),
	}
}

func item(sid string, idx int64, createdAt int64) map[string]interface{} {
	return map[string]interface{}{
		"SessionID":  map[string]string{"S": sid},
		"EventIndex": map[string]string{"N": itoa(idx)},
		"CreatedAt":  map[string]string{"N": itoa(createdAt)},
		"Fields":     map[string]string{"S": `{"event":"x","id":"1","time":"2020-01-02T03:04:05Z","type":"x"}`},
	}
}

func itoa(v int64) string {
	out := ""
	neg := v < 0
	if neg {
		v = -v
	}
	for {
		out = string(rune('0'+v%10)) + out
		v /= 10
		if v == 0 {
			break
		}
	}
	if neg {
		out = "-" + out
	}
	return out
}

func TestZZDaysBetween(t *testing.T) {
	days := daysBetween(
		time.Date(2021, 1, 30, 23, 0, 0, 0, time.UTC),
		time.Date(2021, 2, 1, 1, 0, 0, 0, time.UTC))
	want := []string{"2021-01-30", "2021-01-31", "2021-02-01"}
	if len(days) != len(want) {
		t.Fatalf("got %v", days)
	}
	for i := range want {
		if days[i] != want[i] {
			t.Fatalf("got %v", days)
		}
	}
	if got := daysBetween(time.Now(), time.Now().Add(-time.Hour)); len(got) != 0 {
		t.Fatalf("expected empty, got %v", got)
	}
}

func TestZZMigrateDateAttribute(t *testing.T) {
	var r recorder
	srv := newMockServer(t, &r, []map[string]interface{}{
		item("sess1", 1, 1609459200), // 2021-01-01
		item("sess2", 2, 1614556800), // 2021-03-01
	}, nil)
	defer srv.Close()
	l := newTestLog(t, srv.URL)
	if err := l.migrateDateAttribute(context.Background()); err != nil {
		t.Fatal(err)
	}
	var scans, updates int
	for _, q := range r.reqs {
		switch q.action {
		case "DynamoDB_20120810.Scan":
			scans++
		case "DynamoDB_20120810.UpdateItem":
			updates++
