			if !ok || len(eav) != 1 {
				t.Fatalf("bad eav: %v", q.body["ExpressionAttributeValues"])
			}
			for _, v := range eav {
				m, _ := v.(map[string]interface{})
				if _, isS := m["S"]; !isS {
					t.Fatalf("expected string bound value, got %v", v)
				}
			}
			key, ok := q.body["Key"].(map[string]interface{})
			if !ok {
				t.Fatalf("missing key: %v", q.body)
			}
			if _, ok := key["SessionID"]; !ok {
				t.Fatalf("key missing SessionID: %v", key)
			}
			if _, ok := key["EventIndex"]; !ok {
				t.Fatalf("key missing EventIndex: %v", key)
			}
		default:
			t.Fatalf("unexpected action %v", q.action)
		}
	}
	if scans != 1 || updates != 2 {
		t.Fatalf("scans=%v updates=%v actions=%v", scans, updates, r.actions())
	}
}

